sys_script_client.script:
function onLoad() {
  var reqType = g_form.getValue('request_type');
  setWhatNeededOptions(reqType);
}

function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading) {
    return;
  }
  setWhatNeededOptions(newValue);
}

function setWhatNeededOptions(reqType) {
  g_form.clearOptions('what_needed');

  if (reqType === 'human_resources') {
    g_form.addOption('what_needed', 'hr1', 'Human Resources 1');
    g_form.addOption('what_needed', 'hr2', 'Human Resources 2');
    g_form.addOption('what_needed', 'other', 'Other');
  } else if (reqType === 'facilities') {
    g_form.addOption('what_needed', 'fac1', 'Facilities 1');
    g_form.addOption('what_needed', 'fac2', 'Facilities 2');
    g_form.addOption('what_needed', 'other', 'Other');
  } else if (reqType === 'legal') {
    g_form.addOption('what_needed', 'leg1', 'Legal 1');
    g_form.addOption('what_needed', 'leg2', 'Legal 2');
    g_form.addOption('what_needed', 'other', 'Other');
  }
}
